(window.__D=window.__D||{})["data/ch04.json"]={"n": 4, "title": "Roman Pontus (AD 64–330, with Basil to 358)", "events": [{"id": "H2-085", "date": "50", "date_end": "95", "date_text": "C. AD 50-95", "precision": "decade", "title": "Jews and the first Christians of Pontus", "summary": "Jews 'from Pontus' are among the crowd at Pentecost in Acts, and Aquila, the companion of Paul, was a Jew born in Pontus. The First Letter of Peter is addressed to the 'exiles of the dispersion in Pontus, Galatia, Cappadocia, Asia and Bithynia'. These are the earliest references to Christianity reaching the region, probably through the Jewish communities of the coastal cities.", "people": ["Aquila (companion of Paul)", "Priscilla"], "sources_primary": ["Acts 2:9; 18:2", "1 Peter 1:1", "Philo, Legatio 281 (Jews in Pontus)"], "sources_modern": ["Mitchell 1993, vol. 2", "Elliott 2000 (1 Peter)"], "confidence": "medium", "disputed": "The date and authorship of 1 Peter are debated (about 65–95).", "main": true, "places": [{"name": "Sinope", "lat": 42.026, "lon": 35.153, "role": "probable early community"}, {"name": "Amisos", "lat": 41.3, "lon": 36.34, "role": "probable early community"}]}, {"id": "C2-001", "date": "50", "date_text": "1st century AD (church tradition; no date given)", "precision": "decade", "title": "The Apostle Andrew at Trapezous: the founding tradition", "summary": "Chrysanthos puts the Apostle Andrew at the head of his list of the bishops of Trapezous. Following Symeon Metaphrastes and the Menaion (30 November), he has Andrew come to Trapezous twice from Amisos and preach also at Sousourmaina, Apsaros, Phasis and Sebastopolis. A cave of St Andrew below the later metropolitan church of St Gregory of Nyssa was still used for the liturgy on 30 November. He quotes Joseph Lazaropoulos (14th c.) that 'our whole people never received any other belief about the faith' ('μὴ ἄλλην δόξαν δεδέχθαι ποτὲ περὶ πίστεως ὅλον τὸ φῦλον ἡμῶν').", "people": ["Andrew the Apostle"], "sources_primary": ["Symeon Metaphrastes, Life of St Andrew (as cited by Chrysanthos)", "Menaion, 30 November", "Joseph Lazaropoulos, on the miracles of St Eugenios (14th c.)"], "sources_modern": ["Chrysanthos 1933 (Chrysanthos Philippides, Ἡ Ἐκκλησία Τραπεζοῦντος, Ἀρχεῖον Πόντου 4–5, Athens 1933), pp. 112–114; list p. 789"], "confidence": "low", "disputed": "This is tradition only: Chrysanthos' sources are medieval hagiography and liturgy. Andrew is a founder figure, not a resident bishop.", "main": true, "places": [{"name": "Trapezous (Trebizond, Trabzon)", "lat": 41.005, "lon": 39.73, "role": "preaching (tradition); cave of St Andrew"}, {"name": "Amisos (Samsun)", "lat": 41.29, "lon": 36.33, "role": "starting point (tradition)"}, {"name": "Sousourmaina (Sürmene)", "lat": 40.91, "lon": 40.12, "role": "preaching (tradition)"}, {"name": "Apsaros (Gonio)", "lat": 41.573, "lon": 41.573, "role": "preaching (tradition)"}, {"name": "Phasis (Poti)", "lat": 42.15, "lon": 41.67, "role": "preaching (tradition)"}, {"name": "Sebastopolis (Sukhumi)", "lat": 43.0, "lon": 41.02, "role": "preaching (tradition)"}]}, {"id": "H2-086", "date": "58", "date_text": "AD 58", "precision": "year", "title": "Trapezous supplies Corbulo's Armenian war", "summary": "In Corbulo's war with Parthia over Armenia, supplies came by the Black Sea through Trapezous and up over the Pontic mountains. This is the first clear sign of Trapezous' role as the sea gate of the Armenian frontier, which defined it for the next six centuries.", "people": ["Gnaeus Domitius Corbulo", "Nero"], "sources_primary": ["Tacitus, Annals 13.39.1"], "sources_modern": ["Mitford 2018", "Bryer & Winfield 1985"], "confidence": "medium", "main": true, "places": [{"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "supply port"}, {"name": "Upper Euphrates route (Satala)", "lat": 40.03, "lon": 39.6, "role": "route inland"}]}, {"id": "H2-087", "date": "64", "date_text": "AD 64", "precision": "year", "title": "Nero annexes Pontus Polemoniacus", "summary": "Polemon II gave up his kingdom and Nero made it a province; the coins of Neocaesarea, Trapezous and other cities count a new era from 64. The kingdom was attached to Galatia as Pontus Polemoniacus, and the royal fleet became the Roman Pontic fleet. With this, all of Pontus was under direct Roman rule.", "people": ["Nero", "Polemon II"], "sources_primary": ["Suetonius, Nero 18", "Eutropius 7.14.1", "Aurelius Victor, De Caesaribus 5.2", "Tacitus, Histories 3.47", "City coin eras"], "sources_modern": ["Marek 1993", "Mitchell 1993, vol. 1", "Magie 1950"], "confidence": "high", "disputed": "Some king lists end Polemon's reign in 62/63; the city eras support 64.", "main": true, "places": [{"name": "Neocaesarea (Kabeira-Sebaste, Niksar)", "lat": 40.592, "lon": 36.955, "role": "renamed; era AD 64"}, {"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "annexed; fleet base"}, {"name": "Polemonion", "lat": 41.05, "lon": 37.52, "role": "annexed"}, {"name": "Kerasous-Pharnakeia", "lat": 40.917, "lon": 38.388, "role": "annexed"}]}, {"id": "H2-088", "date": "64", "date_text": "AD 64", "precision": "decade", "title": "Borders AD 64: the provinces of Pontus", "summary": "After 64, western Pontus (Amastris, Sinope, Amisos, Pompeiopolis, Neapolis) lay in the province of Bithynia et Pontus; Pontus Galaticus (Amaseia, Zela, Sebastopolis, Sebasteia, Komana) and the new Pontus Polemoniacus (Neocaesarea, Polemonion, Kerasous, Trapezous) were both attached to Galatia; Cappadocia lay to the south, and Lesser Armenia stayed under client kings until 72.", "people": ["Nero"], "sources_primary": ["Ptolemy, Geography 5.6", "Coin eras"], "sources_modern": ["Marek 1993", "Mitchell 1993"], "confidence": "medium", "disputed": "The exact line between Bithynia et Pontus and Pontus Galaticus west of Amisos is uncertain.", "main": true, "places": [{"name": "Sinope", "lat": 42.026, "lon": 35.153, "role": "Bithynia et Pontus"}, {"name": "Amisos", "lat": 41.3, "lon": 36.34, "role": "Bithynia et Pontus"}, {"name": "Amaseia", "lat": 40.653, "lon": 35.833, "role": "Pontus Galaticus (Galatia)"}, {"name": "Neocaesarea", "lat": 40.592, "lon": 36.955, "role": "Pontus Polemoniacus (Galatia)"}, {"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "Pontus Polemoniacus (Galatia)"}, {"name": "Caesarea", "lat": 38.72, "lon": 35.49, "role": "Cappadocia"}, {"name": "Lesser Armenia", "lat": 40.19, "lon": 38.12, "role": "client kingdom until 72"}]}, {"id": "H2-089", "date": "66", "date_text": "AD 66 (speech) / 75-79 (written)", "precision": "year", "title": "Forty warships keep the Black Sea", "summary": "In the speech Josephus gives Agrippa II, the peoples round the Black Sea and the Maeotis (Heniochoi, Colchians, Taurians, Bosporans) are kept in order by 3,000 soldiers and 40 warships, which have made a once unnavigable sea safe. It is the earliest description of the classis Pontica, based at Trapezous.", "people": ["Agrippa II", "Flavius Josephus"], "sources_primary": ["Josephus, Jewish War 2.366-367"], "sources_modern": ["Mitford 2018", "Starr 1960 (The Roman Imperial Navy)"], "confidence": "medium", "disputed": "The speech is rhetorical, and the figures may be Josephus' own.", "main": true, "places": [{"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "fleet base"}]}, {"id": "H2-090", "date": "69", "date_text": "AD 69", "precision": "year", "title": "Anicetus' revolt at Trapezous", "summary": "Anicetus, a freedman of Polemon II and former commander of the royal fleet, rose for Vitellius against Vespasian. He seized Trapezous, 'a city of ancient fame founded by Greeks at the far end of the Pontic coast', killed the cohort there (former royal auxiliaries given Roman citizenship) and burned the fleet. Vespasian's officer Virdius Geminus caught him at the mouth of the Chobos in Colchis, where the king of the Sedochezi handed him over.", "people": ["Anicetus", "Virdius Geminus", "Vespasian", "Vitellius"], "sources_primary": ["Tacitus, Histories 3.47-48"], "sources_modern": ["Mitford 2018", "Braund 1994"], "confidence": "high", "main": true, "places": [{"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "seized; fleet burned"}, {"name": "Chobos (Khobi) river mouth", "lat": 42.27, "lon": 41.63, "role": "Anicetus captured"}]}, {"id": "H2-091", "date": "71", "date_end": "76", "date_text": "C. AD 71-76", "precision": "decade", "title": "Vespasian builds the eastern frontier", "summary": "Vespasian joined Galatia and Cappadocia (with the Pontic districts and annexed Lesser Armenia) under a consular legate with legions. Legio XII Fulminata was posted to Melitene and Legio XVI Flavia Firma to Satala on the upper Lykos, and roads were built linking Satala to Trapezous. From now on Pontus was the rear and supply base of the Armenian frontier.", "people": ["Vespasian"], "sources_primary": ["Josephus, Jewish War 7.18", "Suetonius, Vespasian 8.4", "Milestones of the Flavian road programme"], "sources_modern": ["Mitford 2018", "Mitchell 1993, vol. 1", "Speidel 2009 (Heer und Herrschaft)"], "confidence": "high", "disputed": "The date of the garrison at Satala (about 72–76) is approximate.", "main": true, "places": [{"name": "Melitene", "lat": 38.42, "lon": 38.36, "role": "base of XII Fulminata"}, {"name": "Satala (Sadak)", "lat": 40.03, "lon": 39.6, "role": "base of XVI Flavia Firma"}, {"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "port of supply"}, {"name": "Nicopolis", "lat": 40.19, "lon": 38.12, "role": "Lesser Armenia, annexed 72"}]}, {"id": "H2-092", "date": "110", "date_end": "112", "date_text": "C. AD 110-112", "precision": "year", "title": "Pliny the Younger governs Bithynia et Pontus", "summary": "Trajan's special legate Pliny wrote to the emperor from the Pontic part of his province about Sinope's need for an aqueduct and Amisos' status as a free and federate city with its own laws. His famous letter on the Christians, the first pagan account of Christian worship, was probably written in the eastern (Pontic) part of the province, perhaps at Amastris or Amisos.", "people": ["Pliny the Younger", "Trajan"], "sources_primary": ["Pliny, Letters 10.90-93, 10.96-97"], "sources_modern": ["Sherwin-White 1966 (Letters of Pliny)", "Mitchell 1993, vol. 2"], "confidence": "high", "disputed": "The exact years (109–111 or 110–112) and the place where the letter on the Christians (10.96) was written are debated.", "main": true, "places": [{"name": "Sinope", "lat": 42.026, "lon": 35.153, "role": "aqueduct letter"}, {"name": "Amisos", "lat": 41.3, "lon": 36.34, "role": "free city; possible place of the Christian letter"}, {"name": "Amastris", "lat": 41.747, "lon": 32.386, "role": "possible place of the Christian letter"}]}, {"id": "H2-093", "date": "113", "date_text": "C. AD 113", "precision": "decade", "title": "Cappadocia separated from Galatia", "summary": "Under Trajan the great Galatian-Cappadocian command was split. Pontus Galaticus and Pontus Polemoniacus, with Trapezous and the coast to Dioskourias, went with Cappadocia, whose governor commanded the two legions; Arrian later held this post.", "people": ["Trajan"], "sources_primary": ["Ptolemy, Geography 5.6", "Arrian, Periplus 1-11"], "sources_modern": ["Mitchell 1993", "Mitford 2018"], "confidence": "medium", "disputed": "The year of the division (107–113) is debated.", "main": true, "places": [{"name": "Caesarea", "lat": 38.72, "lon": 35.49, "role": "capital of Cappadocia"}, {"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "in Cappadocia"}, {"name": "Amaseia", "lat": 40.653, "lon": 35.833, "role": "in Cappadocia"}]}, {"id": "H2-094", "date": "114", "date_text": "AD 114", "precision": "year", "title": "Trajan at Satala and Elegeia", "summary": "Starting his Parthian war, Trajan came to Satala, where he received client kings of the Caucasus and gave gifts to Anchialus, king of the Heniochoi and Machelones; he then annexed Armenia.", "people": ["Trajan", "Anchialus", "Parthamasiris"], "sources_primary": ["Cassius Dio 68.18-19", "Eutropius 8.3.1"], "sources_modern": ["Bennett 1997 (Trajan)", "Mitford 2018"], "confidence": "medium", "main": true, "places": [{"name": "Satala", "lat": 40.03, "lon": 39.6, "role": "meeting with client kings"}, {"name": "Elegeia (Ilica near Erzurum, approximate)", "lat": 39.95, "lon": 41.1, "role": "Armenian king deposed"}]}, {"id": "H2-095", "date": "117", "date_text": "C. AD 117", "precision": "decade", "title": "Legio XV Apollinaris at Satala", "summary": "Legio XV Apollinaris replaced XVI Flavia Firma at Satala around the end of Trajan's reign and stayed there into the 5th century. With XII Fulminata at Melitene it formed the garrison of Cappadocia.", "people": ["Hadrian"], "sources_primary": ["Arrian, Ektaxis kata Alanon 5-6, 15", "Notitia Dignitatum, Oriens 38.13-14", "Inscriptions from Satala"], "sources_modern": ["Mitford 2018", "Speidel 2009", "Bryer & Winfield 1978, 'Cities of Heraclius', BMGS 4 (repr. Bryer 1980, I), p. 26 (the Trapezous–Satala axis of the old Legio XV Apollinaris; Satala still a station of the Notitia Dignitatum)"], "confidence": "medium", "disputed": "The date of the change (about 114–120) is approximate.", "main": true, "places": [{"name": "Satala", "lat": 40.03, "lon": 39.6, "role": "base of XV Apollinaris"}, {"name": "Melitene", "lat": 38.42, "lon": 38.36, "role": "base of XII Fulminata"}]}, {"id": "H2-096", "date": "130", "date_text": "C. AD 128-140", "precision": "decade", "title": "Aquila of Sinope translates the Bible", "summary": "Aquila, a convert to Judaism from Sinope (in Epiphanius' story a relative of Hadrian), made a strictly literal Greek translation of the Hebrew Bible used by Greek-speaking Jews for centuries.", "people": ["Aquila of Sinope", "Hadrian"], "sources_primary": ["Irenaeus, Against Heresies 3.21.1", "Epiphanius, On Weights and Measures 14-15"], "sources_modern": ["Fernandez Marcos 2000 (The Septuagint in Context)"], "confidence": "medium", "disputed": "The link to Hadrian is late legend.", "main": true, "places": [{"name": "Sinope", "lat": 42.026, "lon": 35.153, "role": "Aquila's city"}]}, {"id": "H2-097", "date": "131", "date_end": "132", "date_text": "AD 131/132", "precision": "year", "title": "Arrian's Periplus: the governor sails from Trapezous to Sebastopolis", "summary": "Arrian of Nicomedia, governor of Cappadocia, inspected the forts of the eastern Black Sea and sent Hadrian a Greek report. From Trapezous he sailed to Hyssou Limen (180 stades; a cohort and 20 horse), Athenai, Apsaros (five cohorts), Phasis (a fort with 400 picked men) and Sebastopolis-Dioskourias, the last Roman post, about 2,260 stades in all. He lists the client peoples and kings on the way, including the first mention of the Lazoi (king Malassas) and the Sannoi; the death of King Kotys II of the Bosporus (17.3) dates the work to 131/132.", "people": ["Arrian of Nicomedia", "Hadrian", "Malassas (king of the Lazoi)", "Anchialus (king of the Heniochoi and Machelones)", "Julianus (king of the Apsilai)", "Rhesmagas (king of the Abasgoi)", "Spadagas (king of the Sanigai)"], "sources_primary": ["Arrian, Periplus Ponti Euxini 1-11 (voyage), 11.1-3 (peoples), 12-25 (coastal list), 17.3 (death of Kotys)"], "sources_modern": ["Liddle 2003 (translation and commentary)", "Silberman 1995 (Bude)", "Mitford 2018", "Bryer & Winfield 1985", "Bryer & Winfield 1978, 'Cities of Heraclius', BMGS 4 (repr. Bryer 1980, I), p. 27 (Arrian’s Hyssou Limen, a one-cohort post, = the Ysiporto of the Notitia Dignitatum; located at the walled camp near Canayer, by the later Herakleia/Araklı)"], "confidence": "high", "disputed": "Arrian's stage figures do not add up exactly to his total of 2,260 stades, and some identifications (Hyssou Limen, the Prytanis, the Pyxites) are disputed. Whether the Greek Periplus is a literary companion to a lost Latin report is debated. Bryer & Winfield (1978, British) place Hyssou Limen at the rectangular Roman camp (200 × 300 m) near Canayer, inland of the coastal fort of Sourmaina, 1 km from Araklı, the natural port for the direct route up the Kara Dere valley to Satala.", "main": true, "places": [{"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "waypoint 1: start"}, {"name": "Hyssou Limen (Arakli/Surmene area; identification debated)", "lat": 40.94, "lon": 40.06, "role": "waypoint 2: cohort + 20 horse; 180 stades"}, {"name": "Ophis river (Of)", "lat": 40.95, "lon": 40.27, "role": "waypoint 3: border of Colchis and Thyana; 90 stades"}, {"name": "Rhizios (Rize)", "lat": 41.02, "lon": 40.52, "role": "waypoint 4"}, {"name": "Athenai (Pazar)", "lat": 41.18, "lon": 40.88, "role": "waypoint 5: harbour and temple; storm"}, {"name": "Archabis (Arhavi)", "lat": 41.35, "lon": 41.3, "role": "waypoint 6"}, {"name": "Apsaros (Gonio)", "lat": 41.573, "lon": 41.574, "role": "waypoint 7: five cohorts"}, {"name": "Akampsis (Coruh) mouth", "lat": 41.6, "lon": 41.57, "role": "waypoint 8"}, {"name": "Phasis", "lat": 42.15, "lon": 41.67, "role": "waypoint 9: fort with 400 men"}, {"name": "Chobos (Khobi) mouth", "lat": 42.27, "lon": 41.63, "role": "waypoint 10"}, {"name": "Sebastopolis (Dioskourias, Sukhumi)", "lat": 42.995, "lon": 41.01, "role": "waypoint 11: last Roman post; c. 2,260 stades from Trapezous"}]}, {"id": "H2-098", "date": "131", "date_text": "AD 131/132", "precision": "year", "title": "Trapezous in Arrian's report: Hadrian's harbour", "summary": "At Trapezous Arrian saw the temple of Hermes and new altars, criticised the inscriptions and the statue of Hadrian pointing out to sea, and asked for better ones. Hadrian, who had looked out over the sea from the same spot as Xenophon, was building the city's first proper harbour, where before ships could ride at anchor only in summer.", "people": ["Arrian of Nicomedia", "Hadrian"], "sources_primary": ["Arrian, Periplus 1.1-4, 16.6"], "sources_modern": ["Liddle 2003", "Bryer & Winfield 1985"], "confidence": "high", "disputed": "When Hadrian visited Trapezous, in 129 or 131, is not certain.", "main": true, "places": [{"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "temple, altars, statue, harbour"}]}, {"id": "H2-099", "date": "135", "date_text": "AD 135", "precision": "year", "title": "Arrian turns back the Alans", "summary": "When the Alans raided from the Caucasus into Armenia and Cappadocia, Arrian led legions XV Apollinaris and XII Fulminata with auxiliaries against them; his 'Order of battle against the Alans' survives. The Alans withdrew.", "people": ["Arrian of Nicomedia", "Hadrian", "Alans"], "sources_primary": ["Arrian, Ektaxis kata Alanon", "Cassius Dio 69.15.1"], "sources_modern": ["Bosworth 1977 (HSCP 81)", "Mitford 2018"], "confidence": "high", "disputed": "Where the armies met is not known.", "main": true, "places": [{"name": "Satala", "lat": 40.03, "lon": 39.6, "role": "base of XV Apollinaris (Arrian's army)"}]}, {"id": "H2-100", "date": "144", "date_text": "C. AD 140-144", "precision": "year", "title": "Marcion of Sinope", "summary": "Marcion, a wealthy shipowner of Sinope and, according to Epiphanius, son of the city's bishop, went to Rome, where his break with the church is dated to 144. The story is the earliest evidence for a bishop at Sinope.", "people": ["Marcion of Sinope"], "sources_primary": ["Tertullian, Against Marcion 1.1, 1.19", "Epiphanius, Panarion 42.1-2", "Irenaeus, Against Heresies 1.27.2", "Eusebius, HE 5.13.3"], "sources_modern": ["Lieu 2015 (Marcion and the Making of a Heretic)"], "confidence": "medium", "disputed": "The detail of the bishop father is late (Epiphanius) and may be polemic.", "main": true, "places": [{"name": "Sinope", "lat": 42.026, "lon": 35.153, "role": "Marcion's home"}, {"name": "Rome", "lat": 41.89, "lon": 12.49, "role": "break with the church, 144"}]}, {"id": "H2-101", "date": "165", "date_text": "C. AD 165-180", "precision": "decade", "title": "'Pontus is full of atheists and Christians'", "summary": "Lucian's satire on the oracle-founder Alexander of Abonoteichos has Alexander complain that Pontus is 'full of atheists and Christians', and exclude them from his mysteries. It shows Christians as a visible group in the Pontic cities by the later 2nd century.", "people": ["Lucian", "Alexander of Abonoteichos"], "sources_primary": ["Lucian, Alexander 25, 38"], "sources_modern": ["Mitchell 1993, vol. 2"], "confidence": "medium", "disputed": "It is satire, but the remark had to be believable.", "main": true, "places": [{"name": "Abonoteichos (Inebolu)", "lat": 41.977, "lon": 33.762, "role": "Alexander's oracle"}]}, {"id": "H2-102", "date": "213", "date_text": "C. AD 213", "precision": "decade", "title": "Gregory (Theodore) born at Neocaesarea; studies with Origen", "summary": "Theodore, later called Gregory, was born to a wealthy pagan family of Neocaesarea. With his brother Athenodorus he studied with Origen at Caesarea in Palestine (c. 233-238) and became a Christian; his speech of thanks to Origen survives.", "people": ["Gregory Thaumaturgus", "Athenodorus", "Origen"], "sources_primary": ["Eusebius, HE 6.30", "Gregory Thaumaturgus, Address of Thanksgiving to Origen", "Gregory of Nyssa, Life of Gregory the Wonderworker"], "sources_modern": ["Slusser 1998 (Fathers of the Church 98)", "Mitchell 1999 (in Portraits of Spiritual Authority)"], "confidence": "medium", "disputed": "He was born about 210–215; a few scholars doubt that the Address is his.", "main": true, "places": [{"name": "Neocaesarea (Niksar)", "lat": 40.592, "lon": 36.955, "role": "birthplace"}, {"name": "Caesarea Maritima", "lat": 32.5, "lon": 34.89, "role": "studies with Origen"}]}, {"id": "H2-103", "date": "240", "date_text": "C. AD 240-243", "precision": "decade", "title": "Gregory bishop of Neocaesarea", "summary": "Phaidimos, bishop of Amaseia, consecrated Gregory bishop of his home city. Gregory of Nyssa's Life says he found seventeen Christians there and left only seventeen pagans at his death; it tells of his miracles (moving a rock, drying a lake, stopping the flooding Lykos with his staff), which gave him the name Thaumaturgos, 'Wonderworker'.", "people": ["Gregory Thaumaturgus", "Phaidimos of Amaseia"], "sources_primary": ["Gregory of Nyssa, Life of Gregory the Wonderworker", "Basil, On the Holy Spirit 29.74", "Basil, Letters 28, 204, 207"], "sources_modern": ["Slusser 1998", "Mitchell 1999"], "confidence": "medium", "disputed": "The seventeen Christians and seventeen pagans, and the miracles, are hagiography, written about 380 from family and local tradition.", "main": true, "places": [{"name": "Neocaesarea", "lat": 40.592, "lon": 36.955, "role": "his see"}, {"name": "Amaseia", "lat": 40.653, "lon": 35.833, "role": "see of Phaidimos"}]}, {"id": "H2-104", "date": "250", "date_end": "251", "date_text": "AD 250-251", "precision": "year", "title": "Decian persecution in Pontus", "summary": "During the persecution under Decius Gregory withdrew with his flock into the mountains around Neocaesarea; later tradition lists Pontic martyrs of these years.", "people": ["Gregory Thaumaturgus", "Decius"], "sources_primary": ["Gregory of Nyssa, Life of Gregory the Wonderworker"], "sources_modern": ["Slusser 1998"], "confidence": "medium", "main": true, "places": [{"name": "Neocaesarea", "lat": 40.592, "lon": 36.955, "role": "Gregory's flight"}]}, {"id": "H2-105", "date": "254", "date_end": "256", "date_text": "C. AD 254-256", "precision": "year", "title": "First Gothic raids: Pityous holds, then falls", "summary": "The Borani, carried across the sea in ships of the weakened Bosporan kingdom, attacked Pityous, but the commander Successianus drove them off. In a second expedition they took Pityous, raided towards the Phasis, but failed to take the temple there.", "people": ["Borani", "Successianus", "Valerian"], "sources_primary": ["Zosimus 1.31-33"], "sources_modern": ["Kulikowski 2007 (Rome's Gothic Wars)", "Paschoud 2000 (Zosime I, notes)"], "confidence": "medium", "disputed": "Zosimus gives no year; dates between 253 and 257 are proposed.", "main": true, "places": [{"name": "Bosporus", "lat": 45.35, "lon": 36.47, "role": "waypoint 1: ships supplied"}, {"name": "Pityous (Pitsunda)", "lat": 43.16, "lon": 40.34, "role": "waypoint 2: attacked, later taken"}, {"name": "Phasis", "lat": 42.15, "lon": 41.67, "role": "waypoint 3: temple attacked"}]}, {"id": "H2-106", "date": "257", "date_text": "C. AD 256-257", "precision": "year", "title": "The Goths sack Trapezous", "summary": "After a summer of good weather the raiders' fleet came to Trapezous, a large and populous city with a double wall and, Zosimus says, ten thousand more soldiers than usual. Seeing the garrison idle and drunk, they climbed the walls at night on ladders made from tree trunks, took the city, killed or captured those who did not escape, and destroyed temples, houses and public buildings before sailing home with great booty and many captives. Chrysanthos (1933) takes the 'most holy pappas' addressed in Gregory's Canonical Epistle to be the bishop of Trapezous, the first known by his office; that is his inference.", "people": ["Borani / Goths"], "sources_primary": ["Zosimus 1.33", "Gregory Thaumaturgus, Canonical Epistle"], "sources_modern": ["Kulikowski 2007", "Paschoud 2000", "Bryer & Winfield 1985", "Chrysanthos 1933 (Chrysanthos Philippides, Ἡ Ἐκκλησία Τραπεζοῦντος, Ἀρχεῖον Πόντου 4–5, Athens 1933), p. 50; pp. 128–131/4; p. 216"], "confidence": "medium", "disputed": "The sack is usually dated about 256–257; Zosimus gives no year, and Chrysanthos gives both 257 and 253/4. The 10,000 is Zosimus' figure, probably taken from Dexippus.", "main": true, "places": [{"name": "Pityous", "lat": 43.16, "lon": 40.34, "role": "waypoint 1"}, {"name": "Phasis", "lat": 42.15, "lon": 41.67, "role": "waypoint 2"}, {"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "waypoint 3: sacked"}]}, {"id": "H2-107", "date": "257", "date_end": "258", "date_text": "C. AD 254-258", "precision": "decade", "title": "Gregory's Canonical Epistle: Christians and the raiders", "summary": "In a letter to a fellow bishop, Gregory set penances for Christians of Pontus who during the raids of the 'Boradoi and Goths' had eaten food offered to idols, looted their neighbours' houses, kept captives who had escaped, or even joined the raiders and killed. It is the only contemporary local witness to the raids and shows the breakdown of order in Pontus.", "people": ["Gregory Thaumaturgus", "Boradoi", "Goths"], "sources_primary": ["Gregory Thaumaturgus, Canonical Epistle, canons 1-11"], "sources_modern": ["Heather & Matthews 1991 (The Goths in the Fourth Century, ch. 1)", "Slusser 1998", "Chrysanthos 1933 (Chrysanthos Philippides, Ἡ Ἐκκλησία Τραπεζοῦντος, Ἀρχεῖον Πόντου 4–5, Athens 1933), p. 50; pp. 128–131/4; p. 216"], "confidence": "medium", "disputed": "Whether it refers to the raid of 254 or the sack of Trapezous (c. 257) is debated.", "main": true, "places": [{"name": "Neocaesarea", "lat": 40.592, "lon": 36.955, "role": "Gregory's see"}]}, {"id": "H2-108", "date": "258", "date_text": "C. AD 257-258", "precision": "year", "title": "Third raid: Bithynia burned", "summary": "Encouraged by the booty of Trapezous, other Gothic groups came by land and sea to the Bosporus, took Chalcedon and burned Nicomedia and Nicaea, and plundered Kios, Apameia and Prusa; a flooded river saved Cyzicus.", "people": ["Goths"], "sources_primary": ["Zosimus 1.34-35"], "sources_modern": ["Kulikowski 2007"], "confidence": "medium", "main": true, "places": [{"name": "Chalcedon", "lat": 40.99, "lon": 29.03, "role": "taken"}, {"name": "Nicomedia", "lat": 40.77, "lon": 29.92, "role": "burned"}, {"name": "Nicaea", "lat": 40.43, "lon": 29.72, "role": "burned"}, {"name": "Kios", "lat": 40.433, "lon": 29.157, "role": "plundered"}, {"name": "Prusa", "lat": 40.19, "lon": 29.06, "role": "plundered"}]}, {"id": "H2-109", "date": "264", "date_text": "C. AD 264-265", "precision": "year", "title": "Gregory at the synod of Antioch", "summary": "Gregory and his brother Athenodorus attended the first synod at Antioch against Paul of Samosata, a sign of the Pontic church's standing in the wider church.", "people": ["Gregory Thaumaturgus", "Athenodorus", "Paul of Samosata"], "sources_primary": ["Eusebius, HE 7.28.1"], "sources_modern": ["Slusser 1998"], "confidence": "high", "main": true, "places": [{"name": "Antioch", "lat": 36.2, "lon": 36.16, "role": "synod"}]}, {"id": "H2-110", "date": "270", "date_text": "C. AD 270-275", "precision": "decade", "title": "Death of Gregory the Wonderworker", "summary": "Gregory died at Neocaesarea. His cult made Neocaesarea the spiritual centre of Christian Pontus; Basil's grandmother Macrina the Elder had learned the faith from his disciples.", "people": ["Gregory Thaumaturgus", "Macrina the Elder"], "sources_primary": ["Suda s.v. Gregorios", "Basil, Letter 204.6", "Gregory of Nyssa, Life of Gregory the Wonderworker"], "sources_modern": ["Slusser 1998"], "confidence": "medium", "disputed": "The year is uncertain; 270 is traditional.", "main": true, "places": [{"name": "Neocaesarea", "lat": 40.592, "lon": 36.955, "role": "death and cult"}]}, {"id": "H2-111", "date": "275", "date_end": "276", "date_text": "AD 275-276", "precision": "year", "title": "Goths from the Maeotis raid Pontus and Cappadocia", "summary": "Goths from the Sea of Azov landed and raided through Pontus into Cappadocia, Galatia and Cilicia; the emperor Tacitus and his prefect Florian drove them out.", "people": ["Tacitus (emperor)", "Florian"], "sources_primary": ["Zosimus 1.63", "Historia Augusta, Tacitus 13.2-3", "Zonaras 12.28"], "sources_modern": ["Kulikowski 2007"], "confidence": "medium", "main": true, "places": [{"name": "Pontus (interior)", "lat": 40.653, "lon": 35.833, "role": "raided"}, {"name": "Cappadocia", "lat": 38.72, "lon": 35.49, "role": "raided"}]}, {"id": "H2-112", "date": "293", "date_end": "314", "date_text": "C. AD 293-314", "precision": "decade", "title": "Diocletian's provinces: Diospontus and Pontus Polemoniacus", "summary": "Diocletian divided the Pontic lands into smaller provinces within the diocese of Pontica: Diospontus, with its capital at Amaseia (Amisos and Sinope also belonged to it in later lists), and Pontus Polemoniacus, with its capital at Neocaesarea (Komana, Polemonion, Kerasous, Trapezous). A new legion, I Pontica, was stationed at Trapezous under the dux of Armenia.", "people": ["Diocletian"], "sources_primary": ["Laterculus Veronensis (c. 314)", "Notitia Dignitatum, Oriens 38.13-16", "Hierokles, Synekdemos 701-703 (6th c.)"], "sources_modern": ["Mitchell 1993, vol. 2", "Barnes 1982 (The New Empire)", "Mitford 2018"], "confidence": "medium", "disputed": "The exact date of the division (about 293–305) is not known, and the city lists come from later sources.", "main": true, "places": [{"name": "Amaseia", "lat": 40.653, "lon": 35.833, "role": "capital of Diospontus"}, {"name": "Neocaesarea", "lat": 40.592, "lon": 36.955, "role": "capital of Pontus Polemoniacus"}, {"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "base of legio I Pontica"}, {"name": "Satala", "lat": 40.03, "lon": 39.6, "role": "XV Apollinaris"}, {"name": "Melitene", "lat": 38.42, "lon": 38.36, "role": "XII Fulminata"}]}, {"id": "H2-113", "date": "303", "date_text": "C. AD 303 (traditional)", "precision": "year", "title": "Martyrdom of Eugenios and his companions at Trapezous", "summary": "According to his passion, Eugenios, a Christian of Trapezous, threw down the statue of Mithras on the hill above the city (the Minthrion, today Boztepe), and with Valerian, Kanidios and Akylas was tortured and beheaded in the persecution of Diocletian. He became the patron saint of Trapezous and, from 1204, of the Empire of Trebizond; his feast is 21 January. Chrysanthos (1933, pp. 135-142) tells it from the 14th-century encomium of Constantine Loukites and the texts of Joseph Lazaropoulos: under the dux Lysias, sent by Diocletian and Maximian; the heads and relics were kept in the church of St Eugenios. The cult itself is attested early: Procopius (Buildings 3.7.1) names an aqueduct of the martyr Eugenios at Trapezous under Justinian, and c. 600 the Armenian Anania of Shirak found his teacher Tychikos at the martyr’s shrine (Rosenqvist 1996, pp. 65–66). Loukites’ encomium says a church of St John the Baptist was later built on the spot on Mt Mithrion where the temple of Mithras had stood (Rosenqvist 1996, p. 72).", "people": ["Eugenios", "Valerian", "Kanidios", "Akylas", "Diocletian"], "sources_primary": ["Passion of St Eugenios (BHG 608)", "John Xiphilinos, Encomium (11th c.)", "Joseph (John) Lazaropoulos, Logos and Synopsis of the miracles (14th c.)"], "sources_modern": ["Rosenqvist 1996 (The Hagiographic Dossier of St Eugenios of Trebizond in Codex Athous Dionysiou 154)", "Rosenqvist 2002 (DOP 56)", "Bryer & Winfield 1985", "Chrysanthos 1933 (Chrysanthos Philippides, Ἡ Ἐκκλησία Τραπεζοῦντος, Ἀρχεῖον Πόντου 4–5, Athens 1933), pp. 135–142", "Rosenqvist 1996, The Hagiographic Dossier of St Eugenios of Trebizond, pp. 64–66 (date of the anonymous Passio; earliest evidence of the cult), 72–73 (church of St John on Mt Mithrion; the Seven Brothers of Lazia), 75–77 (feasts of 21 January and 24 June)", "Bryer & Winfield 1978, 'Cities of Heraclius', BMGS 4 (repr. Bryer 1980, I), p. 28 (the Pontic group passions)"], "confidence": "low", "disputed": "The texts are late, the earliest surviving passion centuries after the event, and the date is traditional; a cult of Mithras at Trapezous is supported by 3rd-century city coins showing a Mithraic horseman. The name of the persecuting official varies between versions. On the passion itself: Martin-Hisard (French) sees the anonymous Greek passion as a reworking, after about 800, of a shorter 6th–7th-century text preserved in an Armenian version; Lampsides (Greek) dates it after Symeon Metaphrastes; Rosenqvist (1996, Swedish) thinks a late antique or early medieval date likely for both versions; Bryer & Winfield (1978, British) argue that Eugenios, the most junior of the Five Saints of Arauraka, was 'promoted' between 407 and about 550 to lead the Four Saints of Trapezous, a case of 'hagiological kidnapping'. All agree that the passion tells little about events in 303, and that the martyrs appear as Pontic rather than specifically Trapezuntine heroes (Rosenqvist).", "main": true, "places": [{"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "martyrdom"}, {"name": "Minthrion hill (Boztepe)", "lat": 41.0, "lon": 39.74, "role": "statue of Mithras; later monastery of St Eugenios"}]}, {"id": "H2-114", "date": "303", "date_text": "Uncertain (before c. 400; often c. 303)", "precision": "century", "title": "Phokas the gardener, martyr of Sinope", "summary": "Asterius, bishop of Amaseia, preached c. 400 about Phokas, a gardener of Sinope who gave lodging to the soldiers sent to kill him, dug his own grave in his garden and was beheaded. Phokas became the patron saint of sailors on the Black Sea and beyond, and his tomb-church at Sinope a place of pilgrimage.", "people": ["Phokas of Sinope", "Asterius of Amaseia"], "sources_primary": ["Asterius of Amaseia, Homily 9 (On St Phokas)", "John Chrysostom, Homily on St Phokas"], "sources_modern": ["Maraval 1985 (Lieux saints et pelerinages d'Orient)", "Mitchell 1993, vol. 2"], "confidence": "low", "disputed": "The date is unknown; tradition sometimes merges him with a bishop Phokas of Sinope said to have been martyred under Trajan.", "main": true, "places": [{"name": "Sinope", "lat": 42.026, "lon": 35.153, "role": "martyrdom and tomb"}]}, {"id": "H2-115", "date": "306", "date_text": "C. AD 306", "precision": "year", "title": "Theodore 'Tiron' martyred at Amaseia", "summary": "Theodore, a recruit, burned the temple of the Mother of the Gods at Amaseia and was burned alive; his relics were taken to Euchaita, which became one of the great pilgrimage centres of Asia Minor. Gregory of Nyssa preached his panegyric at the shrine.", "people": ["Theodore Tiron", "Gregory of Nyssa"], "sources_primary": ["Gregory of Nyssa, Encomium of St Theodore", "Passion of Theodore (BHG 1760)"], "sources_modern": ["Haldon 2016 (A Tale of Two Saints)", "Mitchell 1993, vol. 2"], "confidence": "medium", "disputed": "The date, under Galerius or Maximinus about 306, is traditional.", "main": true, "places": [{"name": "Amaseia", "lat": 40.653, "lon": 35.833, "role": "martyrdom"}, {"name": "Euchaita (Avkat, approximate)", "lat": 40.46, "lon": 35.26, "role": "shrine"}]}, {"id": "H2-116", "date": "314", "date_text": "C. AD 314", "precision": "decade", "title": "Borders c. AD 314: the late Roman provinces", "summary": "From the Verona List and later lists: Diospontus (later Helenopontus): Amaseia, Amisos, Sinope, Zela, Ibora, Andrapa, Zaliches. Pontus Polemoniacus: Neocaesarea, Komana, Polemonion, Kerasous, Trapezous. Paphlagonia to the west (Gangra, Pompeiopolis), Armenia Minor to the south-east (Satala, Nicopolis, Sebasteia, Melitene), Cappadocia to the south.", "people": ["Diocletian", "Constantine"], "sources_primary": ["Laterculus Veronensis", "Hierokles, Synekdemos", "Justinian, Novel 28 (preface)"], "sources_modern": ["Mitchell 1993", "Barnes 1982"], "confidence": "medium", "disputed": "Some cities moved between provinces in the 4th century.", "main": true, "places": [{"name": "Amaseia", "lat": 40.653, "lon": 35.833, "role": "Diospontus"}, {"name": "Sinope", "lat": 42.026, "lon": 35.153, "role": "Diospontus"}, {"name": "Amisos", "lat": 41.3, "lon": 36.34, "role": "Diospontus"}, {"name": "Zela", "lat": 40.303, "lon": 35.886, "role": "Diospontus"}, {"name": "Neocaesarea", "lat": 40.592, "lon": 36.955, "role": "Pontus Polemoniacus"}, {"name": "Komana", "lat": 40.355, "lon": 36.635, "role": "Pontus Polemoniacus"}, {"name": "Polemonion", "lat": 41.05, "lon": 37.52, "role": "Pontus Polemoniacus"}, {"name": "Kerasous", "lat": 40.917, "lon": 38.388, "role": "Pontus Polemoniacus"}, {"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "Pontus Polemoniacus"}, {"name": "Gangra", "lat": 40.6, "lon": 33.615, "role": "Paphlagonia"}, {"name": "Satala", "lat": 40.03, "lon": 39.6, "role": "Armenia Minor"}, {"name": "Sebasteia", "lat": 39.75, "lon": 37.015, "role": "Armenia Minor"}]}, {"id": "H2-117", "date": "315", "date_text": "C. AD 315", "precision": "year", "title": "Council of Neocaesarea", "summary": "Bishops met at Neocaesarea shortly after the council of Ancyra (314) and issued fifteen canons on clerical marriage, penance and church order, which entered the canon law of the Eastern church.", "people": ["Bishops of Pontus and neighbouring provinces"], "sources_primary": ["Canons of Neocaesarea (Joannou, Discipline generale antique, vol. 1.2)"], "sources_modern": ["Hefele-Leclercq, Histoire des conciles 1.1"], "confidence": "medium", "disputed": "Dated between 314 and 325.", "main": true, "places": [{"name": "Neocaesarea", "lat": 40.592, "lon": 36.955, "role": "council"}]}, {"id": "H2-118", "date": "320", "date_text": "C. AD 320-322", "precision": "year", "title": "Licinius' persecution at Amaseia; Basil of Amaseia", "summary": "Eusebius records that under Licinius churches at Amaseia and other cities of Pontus were pulled down or closed. Basil, bishop of Amaseia, was martyred; his passion says his body was thrown into the sea and recovered at Sinope.", "people": ["Licinius", "Basil of Amaseia"], "sources_primary": ["Eusebius, HE 10.8.15", "Eusebius, Life of Constantine 2.1-2", "Passion of Basil of Amaseia (BHG 239)"], "sources_modern": ["Barnes 1981 (Constantine and Eusebius)"], "confidence": "medium", "disputed": "The passion of Basil is late; Eusebius is contemporary.", "main": true, "places": [{"name": "Amaseia", "lat": 40.653, "lon": 35.833, "role": "persecution"}, {"name": "Sinope", "lat": 42.026, "lon": 35.153, "role": "Basil's body recovered"}]}, {"id": "H2-119", "date": "325", "date_text": "AD 325", "precision": "year", "title": "Pontic bishops at Nicaea", "summary": "Bishops from Pontus took part in the council of Nicaea. In Gelzer's edition of the subscription lists (1898), Pontus Polemoniacus is represented by Longinus of Neocaesarea, Domnus of Trapezous and Stratophilus of Pityous; Eutychianus of Amaseia, Elpidius of Komana, Heraclius of Zela and Acrites of Diospontus appear together in another group. No bishop of Sinope, Amisos or Kerasous appears, and the bishop 'of Koloneia' in the Cappadocian group is of Koloneia-Archelais in Cappadocia, not of Pontic Koloneia. Chrysanthos (1933), following Gelzer, adds a bishop of Kerasous, Akouarios.", "people": ["Longinus of Neocaesarea", "Domnus of Trapezous", "Stratophilus of Pityous", "Constantine"], "sources_primary": ["Nicene subscription lists (Gelzer, Hilgenfeld & Cuntz, Patrum Nicaenorum nomina, 1898, pp. LX–LXIV), as transcribed by province by G. L. Thompson (Fourth-Century Christianity, fourthcentury.com)"], "sources_modern": ["Bryer & Winfield 1985", "Chrysanthos 1933 (Chrysanthos Philippides, Ἡ Ἐκκλησία Τραπεζοῦντος, Ἀρχεῖον Πόντου 4–5, Athens 1933), p. 142; pp. 186–188; list p. 789"], "confidence": "medium", "disputed": "The lists survive in several versions that do not agree in every name; Chrysanthos' Akouarios of Kerasous is not in Gelzer's list.", "main": true, "places": [{"name": "Nicaea", "lat": 40.43, "lon": 29.72, "role": "council"}, {"name": "Trapezous", "lat": 41.005, "lon": 39.727, "role": "see of Domnus"}, {"name": "Pityous", "lat": 43.16, "lon": 40.34, "role": "see of Stratophilus"}, {"name": "Neocaesarea (Niksar)", "lat": 40.592, "lon": 36.955, "role": "see of Longinus"}]}, {"id": "H2-120", "date": "330", "date_text": "C. AD 327-337", "precision": "decade", "title": "Diospontus renamed Helenopontus", "summary": "Constantine renamed Diospontus after his mother Helena; the name Helenopontus is used from then until the 7th century. Justinian's Novel 28 later recalled the name's origin.", "people": ["Constantine", "Helena"], "sources_primary": ["Justinian, Novel 28 (preface)"], "sources_modern": ["Mitchell 1993, vol. 2"], "confidence": "medium", "disputed": "The exact date of the renaming is unknown.", "main": true, "places": [{"name": "Amaseia", "lat": 40.653, "lon": 35.833, "role": "capital of Helenopontus"}]}, {"id": "H2-121", "date": "358", "date_text": "C. AD 357-358", "precision": "year", "title": "Basil at Annesi on the Iris", "summary": "Basil of Caesarea, back from his studies, withdrew to his family's estate at Annesi on the Iris near Ibora, where his mother Emmelia and sister Macrina had turned the household into a community. In a letter to Gregory of Nazianzus he describes the place: a high wooded mountain, a plain enclosed by ravines, and in front the river, 'the most rapid stream I know', falling over a precipice. The retreat was the cradle of Basil's monastic rules.", "people": ["Basil of Caesarea", "Gregory of Nazianzus", "Macrina the Younger", "Emmelia", "Gregory of Nyssa"], "sources_primary": ["Basil, Letter 14 (and 3, 223)", "Gregory of Nazianzus, Letters 4-6", "Gregory of Nyssa, Life of Macrina"], "sources_modern": ["Silvas 2005 (The Asketikon of St Basil the Great), pp. 43-45", "Rousseau 1994 (Basil of Caesarea)"], "confidence": "medium", "disputed": "Where Annesi lay is uncertain: Silvas places it at Uluköy (Sonusa), near where the Lykos joins the Iris; older works put it near Turhal, taken for Ibora (Turhal is more likely the ancient Gaziura).", "main": true, "places": [{"name": "Annesi (Annisa), probably at Ulukoy (former Sonusa), Tasova", "lat": 40.786, "lon": 36.418, "role": "Basil's retreat; Macrina's community"}, {"name": "Neocaesarea", "lat": 40.592, "lon": 36.955, "role": "family home city"}]}], "turkish": [], "synthesis": "## The end of the kingdom\n\nIn AD 64 Polemon II gave up his kingdom and Nero made it a province (Suetonius, *Nero* 18). Some king lists end his reign in 62 or 63, but the coins of Neocaesarea, Trapezous and the other cities count a new era from 64, and that is the date usually accepted. The eastern half of the old kingdom, with Neocaesarea (the old Kabeira, now Niksar), Polemonion, Kerasous and Trapezous, became Pontus Polemoniacus and was attached to Galatia; the royal fleet became the Roman *classis Pontica*, based at Trapezous. All of Pontus was now under direct Roman rule.\n\nFive years later, in the civil war of 69, Anicetus, a freedman of the old king and once commander of his fleet, rose for Vitellius against Vespasian. He seized Trapezous, which Tacitus calls \"a city of ancient fame founded by Greeks\", killed the cohort stationed there and burned the fleet. Vespasian's officer Virdius Geminus caught him at the mouth of the Chobos in Colchis, where a local king handed him over (Tacitus, *Histories* 3.47–48).\n\n## The rear of the frontier\n\n<figure class=\"nmap\"><a href=\"maps/ch04_frontier.jpg\" target=\"_blank\" rel=\"noopener\"><img src=\"maps/ch04_frontier.jpg\" width=\"2000\" height=\"1280\" loading=\"lazy\" alt=\"Relief map from Amastris to Colchis showing the legions at Satala and Melitene, the road from Trapezous, Arrian's voyage along the eastern coast with his posts, and the Gothic raids by sea.\"></a><figcaption>The rear of the Roman frontier: the legions at Satala and Melitene, the road from Trapezous (its line is schematic), the posts Arrian inspected on his voyage of 131/2, and the Gothic raids by sea of the 250s. Tap the map to enlarge it. Relief from the AWS Terrain Tiles; coast and rivers from Natural Earth.</figcaption></figure>\n\nTrapezous had already served Rome as a sea gate to Armenia: in Corbulo's war with Parthia, in 58, supplies came by sea to Trapezous and were carried up over the mountains. Vespasian made this permanent. He joined Galatia and Cappadocia, with the Pontic districts and Lesser Armenia, under a consular governor with legions; Legio XII Fulminata went to Melitene and Legio XVI Flavia Firma to Satala on the upper Lykos, and roads were built from Satala over the mountains to Trapezous. From then on Pontus was the rear and supply base of the Armenian frontier. Under Trajan, between 107 and 113, the great command was divided, and the Pontic provinces, with Trapezous and the coast as far as Dioskourias, went with Cappadocia, whose governor commanded the two legions. About the end of Trajan's reign Legio XV Apollinaris replaced XVI at Satala and stayed there into the 5th century. Trajan himself came to Satala in 114, at the start of his Parthian war, and received the client kings of the Caucasus there.\n\nThe western half of Pontus, with Amastris, Sinope and Amisos, stayed in the province of Bithynia and Pontus. Pliny the Younger governed it for Trajan about 110–112, and his letters from the Pontic cities deal with Sinope's need for an aqueduct and with Amisos' rights as a free city with its own laws. His famous letter on the Christians was probably written in the Pontic part of the province, though where exactly is debated.\n\n## Arrian's voyage\n\nAbout 131/132 Arrian of Nicomedia, governor of Cappadocia, inspected the Roman posts on the eastern Black Sea and sent Hadrian a report in Greek, the *Periplus*; the death of King Kotys II of the Bosporus, which it mentions, gives the date. At Trapezous he saw the temple of Hermes, found fault with the altars, the inscriptions and the statue of Hadrian pointing out to sea, and asked for better ones; Hadrian was building the city's first proper harbour, where before ships could ride at anchor only in summer. From there Arrian sailed east: to Hyssou Limen, 180 stades, with a cohort and 20 horsemen; to Athenai; to Apsaros, with five cohorts; to Phasis, a fort with 400 picked men; and on to Sebastopolis, the old Dioskourias, the last Roman post, about 2,260 stades in all, though his stage figures add up to more. He lists the client peoples inland, among them the first Lazoi on record, under their king Malassas, and the Sannoi, the later Tzans. A few years later, about 135, he led the two legions against the Alans when they raided from the Caucasus, and his *Order of Battle against the Alans* survives.\n\nStrabo, born at Amaseia, had written his description of Pontus a century earlier, about AD 18–24, in the reign of Queen Pythodoris. It is the only description of the country by a native: Amaseia, \"our city\", with its two peaks, its water channels and royal tombs (12.3.39); the harbours and walls of Sinope (12.3.11); Amisos and the plain of Themiskyra (12.3.14–15); the iron of the Chaldaioi and the mad honey of the Heptakometai (12.3.18–19); the palace, water-mill and game parks at Kabeira (12.3.30); and the temple-states of Komana and Zela (12.3.32–37). He favours his own family and Lucullus, and says little of much of the interior.\n\n## The Gothic raids\n\nIn the 250s Pontus was raided from the sea. The Borani, carried across in ships of the weakened Bosporan kingdom, attacked Pityous and were driven off by its commander, Successianus; on a second expedition they took it and raided towards the Phasis. Then, after a summer of good weather, they came to Trapezous, a large and populous city with a double wall, held, Zosimus says, by \"ten thousand soldiers above the usual garrison\". Seeing the garrison idle and drunk, the raiders climbed the walls at night on ladders made of tree trunks, took the city, killed or captured those who could not escape, destroyed temples, houses and public buildings, and sailed home with great booty and many captives (Zosimus 1.33). Zosimus gives no year; the sack is usually placed about 256 or 257. Encouraged by the booty, other bands burned Nicomedia and Nicaea, and about 275 Goths from the Sea of Azov raided through Pontus into Cappadocia, Galatia and Cilicia until the emperor Tacitus and his prefect Florian drove them out.\n\nThe only local witness is a letter of Gregory, bishop of Neocaesarea, to a fellow bishop, the *Canonical Epistle*. It sets penances for Christians of Pontus who, during the raids of the \"Boradoi and Goths\", had eaten food offered to idols, looted their neighbours' houses, kept captives who had escaped, or even joined the raiders and killed. Whether it refers to the first raid or to the sack of Trapezous is debated.\n\n## The first Christians\n\n<figure class=\"nmap\"><a href=\"maps/ch04_church.jpg\" target=\"_blank\" rel=\"noopener\"><img src=\"maps/ch04_church.jpg\" width=\"2000\" height=\"1040\" loading=\"lazy\" alt=\"Relief map of the Pontus from Abonoteichos to Trapezous showing the sees whose bishops signed at Nicaea, the cities of the martyrs, Annesi, and the provinces of Diospontus and Pontus Polemoniacus.\"></a><figcaption>The first Christians of the Pontus: the sees whose bishops signed at Nicaea in 325, the cities of the martyrs, Gregory the Wonderworker's Neocaesarea, and Annesi, where Basil and Macrina lived, whose site is uncertain. Tap the map to enlarge it. Relief from the AWS Terrain Tiles; coast and rivers from Natural Earth.</figcaption></figure>\n\nChristianity came early to Pontus, probably through the Jewish communities of the coastal cities. Jews \"from Pontus\" are among the crowd at Pentecost in Acts (2:9); Aquila, Paul's companion, was a Jew born in Pontus (Acts 18:2); and the First Letter of Peter is addressed to the exiles \"in Pontus, Galatia, Cappadocia, Asia and Bithynia\". In the 2nd century Sinope produced two famous figures: Aquila, a convert to Judaism, whose strictly literal Greek translation of the Hebrew Bible Greek-speaking Jews used for centuries, and Marcion, a wealthy shipowner who broke with the church at Rome in 144. Epiphanius, writing much later and with hostile intent, says Marcion's father was the bishop of Sinope. By the 160s Lucian could have his oracle-monger Alexander of Abonoteichos complain that Pontus was \"full of atheists and Christians\"; it is satire, but the remark had to be believable.\n\nThe church of Pontus took its shape from Gregory the Wonderworker. Born Theodore, to a rich pagan family of Neocaesarea, about 210–215, he studied with Origen at Caesarea in Palestine with his brother Athenodorus, became a Christian, and about 240 was made bishop of his home city by Phaidimos, bishop of Amaseia. In the Decian persecution of 250 he withdrew with his flock into the mountains; in 264 he and his brother attended the synod of Antioch against Paul of Samosata. He died at Neocaesarea, traditionally in 270. His *Life*, written by Gregory of Nyssa about 380 from family and local tradition, says that he found seventeen Christians in the city and left only seventeen pagans, and tells of the miracles that gave him his name, among them stopping the flooding Lykos with his staff. The numbers and the miracles belong to the legend, but the cult was real: Basil's grandmother, Macrina the Elder, had learned the faith from Gregory's disciples, and Neocaesarea became the spiritual centre of Christian Pontus.\n\n## The martyrs and the new provinces\n\nDiocletian divided the Pontic lands into smaller provinces: Diospontus, with its capital at Amaseia, and Pontus Polemoniacus, with its capital at Neocaesarea and with Komana, Polemonion, Kerasous and Trapezous. A new legion, I Pontica, was stationed at Trapezous. Constantine later renamed Diospontus Helenopontus, after his mother.\n\nThe Great Persecution gave the Pontic cities their patron saints. Eugenios of Trapezous, by the account of his passion, threw down the statue of Mithras on the hill above the city, the Minthrion, today's Boztepe, and was beheaded with his companions Valerian, Kanidios and Akylas; he became the patron of Trapezous, and from 1204 of the Empire of Trebizond. The surviving texts are centuries later than the events, and the date about 303 is traditional, but third-century coins of Trapezous do show a Mithraic horseman, and the cult is old: Procopius names an aqueduct \"of the martyr Eugenios\" at Trapezous under Justinian (*Buildings* 3.7.1). Theodore, a young recruit, burned the temple of the Mother of the Gods at Amaseia and was burned alive, about 306; his relics went to Euchaita, which became one of the great pilgrimage centres of Asia Minor, and Gregory of Nyssa preached his panegyric there. Phokas, a gardener of Sinope, gave lodging to the soldiers sent to kill him, dug his own grave in his garden and was beheaded; Asterius, bishop of Amaseia, preached about him about 400, and Phokas became the patron of sailors on the Black Sea and beyond. His date is unknown.\n\nUnder Licinius, about 320, churches at Amaseia and other Pontic cities were pulled down or closed (Eusebius, *Church History* 10.8.15); the late passion of Basil, bishop of Amaseia, says that he was martyred and his body thrown into the sea and recovered at Sinope. Soon after the council of Ancyra in 314, bishops met at Neocaesarea and issued fifteen canons on clerical marriage, penance and church order, which entered the canon law of the Eastern church. Pontic bishops sat at Nicaea in 325. In the subscription lists as edited by Gelzer (1898), Longinus of Neocaesarea, Domnus of Trapezous and Stratophilus of Pityous sign for Pontus Polemoniacus, and Eutychianus of Amaseia, Elpidius of Komana and Heraclius of Zela also appear; the lists survive in several versions that do not agree in every name, and no bishop of Sinope or Amisos is recorded.\n\nAbout 358 Basil, back from his studies, withdrew to his family's estate at Annesi on the Iris, where his mother Emmelia and his sister Macrina had turned the household into a community. In a letter to Gregory of Nazianzus (Letter 14) he describes the place: a high wooded mountain, a plain shut in by ravines, and in front the river, falling over a precipice. The rules Basil wrote for his communities became the foundation of Greek monastic life. Where Annesi lay is uncertain: Silvas (2005) places it at Uluköy, near where the Lykos joins the Iris; older works put it near Turhal.\n\n## The numbers, and who gives them\n\n| What | Figure | Who gives it |\n|---|---|---|\n| Roman force keeping the Black Sea, AD 66 | 40 warships and 3,000 men | Josephus, *Jewish War* 2.366–367, in a speech; rhetorical |\n| Hyssou Limen; Apsaros; Phasis, about 131 | a cohort and 20 horsemen; 5 cohorts; 400 men | Arrian, *Periplus* |\n| Trapezous to Sebastopolis | about 2,260 stades (about 420 km) | Arrian; his stage figures add up to more |\n| Garrison of Trapezous, about 257 | 10,000 above the usual number | Zosimus, probably from Dexippus |\n| Christians of Neocaesarea under Gregory | 17 at the start; 17 pagans left at his death | Gregory of Nyssa; hagiography |\n\n## Legend and evidence\n\nChrysanthos, metropolitan of Trebizond, put the Apostle Andrew at the head of his list of the city's bishops; following Symeon Metaphrastes and the Menaion, he has Andrew preach at Trapezous on the way from Amisos to the Caucasus, and a cave of St Andrew below the church of St Gregory of Nyssa was used for the liturgy on his feast, 30 November. It is a founding tradition known only from medieval hagiography and liturgy. The stories of Eugenios and the Mithras statue, of Gregory's miracles and of Marcion's bishop father are likewise later tradition; the contemporary evidence for these centuries is Arrian's report, Gregory's letter, Basil's letters, Eusebius, the city coins and the inscriptions.\n\n## The sources\n\nTacitus and Suetonius give the annexation and the revolt of 69, and Josephus the Black Sea fleet. Arrian's *Periplus* is the governor's own report of his voyage, port by port. Zosimus, writing about 500, probably from the lost history of Dexippus, gives the Gothic raids. Gregory's *Canonical Epistle* is a bishop's letter from the time of the raids. Gregory of Nyssa's *Life of Gregory*, the passions of Eugenios and Asterius' sermon on Phokas tell the saints of Pontus as their churches remembered them. Basil's letters and Eusebius are contemporary witnesses. The Verona List, the *Notitia Dignitatum* and Hierokles list the provinces and garrisons. Among modern works, Mitchell's *Anatolia* (1993) and Marek (1993) treat the provinces, the cities and the coming of Christianity; Magie (1950) gives the most detailed narrative; Mitford (2018) covers the frontier, Satala and Trapezous; Liddle (2003) and Silberman (1995) edit Arrian's *Periplus*; Bryer & Winfield (1985) give the topography of the coast; Kulikowski (2007) and Paschoud (2000) treat the Gothic raids; Slusser (1998) and Mitchell (1999) Gregory the Wonderworker; Rosenqvist (1996, 2002) Eugenios; and Silvas (2005) Basil and Annesi.\n"};
